"""Returns True if a grant overlaps with a given frequency range.

  If the lowFrequency or the highFrequency of the grant falls within the
  low and high frequencies of the given range then the grant is considered
  to be overlapping.

  Args:
    grant: A |GrantData| object dictionary defined in SAS-SAS spec
    frequency_range: The frequency range in Hz as a dictionary with keys
       'lowFrequency' and 'highFrequency'.
  """
def checkForOverlappingGrants(grant: Any, frequency_range: Any) -> object {
    low_frequency_cbsd = grant['operationParam']['operationFrequencyRange'][
        'lowFrequency'
    ];
    high_frequency_cbsd = grant['operationParam']['operationFrequencyRange'][
        'highFrequency'
    ];
    low_frequency = frequency_range['lowFrequency'];
    high_frequency = frequency_range['highFrequency'];
    assert (low_frequency_cbsd < high_frequency_cbsd);
    assert (low_frequency < high_frequency);
    return (
        (low_frequency_cbsd < high_frequency) and (low_frequency < high_frequency_cbsd)
    );
}

"""Convenience function that implements part of the spin-1 width formula.

    :param m_med: mediator mass
    :type m_med: float
    :param m_f: fermion mass
    :type m_f: float
    """
def alpha(m_med: Any, m_f: Any) -> object {
    return (1 + ((2 * (m_f ** 2)) / (m_med ** 2)));
}

"""

    :param effective_sample_size:
    :param batch_size:
    :param forgetting_factor:
    :return:

    >>> update_effective_sample_size(1.0,1.0,1.0)
    (2.0, 1.0)

    """
def update_effective_sample_size(
    effective_sample_size: Any, batch_size: Any, forgetting_factor: Any
) -> object {
    updated_sample_size = (effective_sample_size * forgetting_factor) + batch_size;
    weight = (
        1
        - (((effective_sample_size * 1.0) - batch_size) / (effective_sample_size * 1.0))
    );
    return (updated_sample_size, weight);
}

"""
  Helper sorting the named modules into existing and not existing.
  """
def _find_imports(*args: Any) -> object {
    import importlib;
    exists = {True: [], False: []};
    for name in args {
        name = name.replace('-', '_');
        try {
            importlib.import_module(name);
            exists[True].append(name);
        } except ImportError {
            exists[False].append(name);
        }
    }
    return exists;
}

